public abstract class Vec3fStruct
implements Struct {
    private static final int NAME_X = StringPool.computeIfAbsent("x");
    private static final int NAME_Y = StringPool.computeIfAbsent("y");
    private static final int NAME_Z = StringPool.computeIfAbsent("z");

    @Override
    public Object getProperty(int name) {
        if (name == NAME_X) {
            return Float.valueOf(this.getX());
        }
        if (name == NAME_Y) {
            return Float.valueOf(this.getY());
        }
        if (name == NAME_Z) {
            return Float.valueOf(this.getZ());
        }
        return null;
    }

    protected abstract float getX();

    protected abstract float getY();

    protected abstract float getZ();

    @Override
    public void putProperty(int name, Object value) {
    }

    public String toString() {
        return String.format("vec3{x=%.2f, y=%.2f, z=%.2f}", Float.valueOf(this.getX()), Float.valueOf(this.getY()), Float.valueOf(this.getZ()));
    }

    @Override
    public Struct copy() {
        return this;
    }
}

